        if np.any(neg_mask):
            terms[neg_mask] = -np.inf
        entropy = terms.sum()

    if isinstance(entropy, (int, float)) and np.isinf(entropy):
        if entropy > 0:
            print('inf')
        else:
            print('-inf')
    elif np.isnan(entropy):
        print('nan')
    else:
        print(f"{entropy:.10f}")

