    except:
        print('Invalid input'); return
    repls = []
    for i in range(M):
        if idx >= len(data):
            print('Invalid input'); return
        parts = data[idx].split(','); idx += 1
        if len(parts) < 2:
            print('Invalid input'); return
        old = parts[0].strip()
        new = parts[1].strip()
        repls.append((old, new))

    # apply replacements
    def apply_repl(v):
        for old, new in repls:
            if v == old:
                v = new
        return v

    header = [apply_repl(h) for h in header]
    rows = [[apply_repl(c) for c in row] for row in rows]

    required = ['feature1','feature2','feature3','feature4','feature5']
    for req in required:
        if req not in header:
            print('Invalid input'); return

    col_idx = {}
    for req in required:
        col_idx[req] = header.index(req)

    results = []
    for req in required:
        ci = col_idx[req]
        vals = []
        for row in rows:
            if ci >= len(row):
                print('Invalid input'); return
            try:
                vals.append(float(row[ci]))
            except:
                print('Invalid input'); return
        if len(vals) == 0:
            print('Invalid input'); return
        n = len(vals)
        mean = sum(vals)/n
        s = sorted(vals)
        if n % 2 == 1:
            median = s[n//2]
        else:
            median = (s[n//2-1]+s[n//2])/2.0
        cnt = Counter(vals)
        maxc = max(cnt.values())
        modecands = [v for v,c in cnt.items() if c == maxc]
        mode = min(modecands)
